import random
def brute_force(height):
    return sum(min(max(height[:i + 1]), max(height[i:])) - height[i] for i in range(len(height)))
def agrees_with_brute_force_on_small_random_lists():
    rng = random.Random(31)
    for _ in range(300):
        height = [rng.randint(0, 6) for _ in range(rng.randint(0, 10))]
        got = trap(list(height))
        assert got == brute_force(height), f"trap({height}) returned {got}, expected {brute_force(height)}"
    return True
